#!/usr/bin/env bash
set -euo pipefail
ZIP="${1:-$HOME/Downloads/sc-lab-v0.158.0-artifacts/sustainable-catalyst-lab-v0.158.0-wordpress.zip}";WP_ROOT="${2:-$HOME/public_html}";[ -f "$ZIP" ]||{ echo "ERROR: missing $ZIP" >&2;exit 1;};[ -d "$WP_ROOT/wp-content/plugins" ]||{ echo "ERROR: WordPress plugins directory not found: $WP_ROOT" >&2;exit 1;};TMP="$(mktemp -d)";trap 'rm -rf "$TMP"' EXIT;unzip -q "$ZIP" -d "$TMP";SRC="$TMP/sustainable-catalyst-lab";[ -d "$SRC" ]||{ echo 'ERROR: plugin payload not found' >&2;exit 1;};TARGET="$WP_ROOT/wp-content/plugins/sustainable-catalyst-lab";STAMP="$(date -u +%Y%m%dT%H%M%SZ)";[ ! -d "$TARGET" ]||cp -a "$TARGET" "$TARGET.backup-v0.158.0-$STAMP";rsync -a --delete "$SRC/" "$TARGET/";cd "$WP_ROOT";wp plugin activate sustainable-catalyst-lab >/dev/null;wp cache flush >/dev/null 2>&1||true;echo 'PASS - WordPress Lab v0.158.0 installed and activated.'
